using EnterpriseERP.Domain.Exceptions;
using EnterpriseERP.Application.Common.Interfaces.Repositories; using EnterpriseERP.Application.Features.SalesInvoices.DTOs; using EnterpriseERP.Domain.Entities.Sales; using MediatR;  namespace EnterpriseERP.Application.Features.SalesInvoices.Queries.GetSalesInvoiceById;  public record GetSalesInvoiceByIdQuery(Guid Id) : IRequest<SalesInvoiceDto>;  public class GetSalesInvoiceByIdQueryHandler : IRequestHandler<GetSalesInvoiceByIdQuery, SalesInvoiceDto> {     private readonly IUnitOfWork _unitOfWork;      public GetSalesInvoiceByIdQueryHandler(IUnitOfWork unitOfWork)     {         _unitOfWork = unitOfWork;     }      public async Task<SalesInvoiceDto> Handle(GetSalesInvoiceByIdQuery request, CancellationToken cancellationToken)     {         var invoice = await _unitOfWork.Repository<SalesInvoice>().GetByIdAsync(request.Id);                  if (invoice == null)             throw new SalesDomainException($"Sales invoice with id {request.Id} not found");          var lines = await _unitOfWork.Repository<SalesInvoiceLine>().FindAsync(x => x.SalesInvoiceId == request.Id);         var customer = await _unitOfWork.Repository<Customer>().GetByIdAsync(invoice.CustomerId);          return new SalesInvoiceDto         {             Id = invoice.Id,             InvoiceNumber = invoice.InvoiceNumber,             InvoiceDate = invoice.InvoiceDate,             CustomerId = invoice.CustomerId,             CustomerName = customer?.Name ?? string.Empty,             BranchId = invoice.BranchId,             WarehouseId = invoice.WarehouseId,             SubTotal = invoice.SubTotal,             DiscountAmount = invoice.DiscountAmount,             TaxAmount = invoice.TaxAmount,             TotalAmount = invoice.TotalAmount,             PaidAmount = invoice.PaidAmount,             RemainingAmount = invoice.RemainingAmount,             Status = invoice.Status.ToString(),             Notes = invoice.Notes,             Lines = lines.Select(l => new SalesInvoiceLineDto             {                 Id = l.Id,                 ItemId = l.ItemId,                 Quantity = l.Quantity,                 UnitPrice = l.UnitPrice,                 DiscountPercent = l.DiscountPercent,                 DiscountAmount = l.DiscountAmount,                 TaxPercent = l.TaxPercent,                 TaxAmount = l.TaxAmount,                 LineTotal = l.LineTotal             }).ToList()         };     } }

